def verify(witness):
    # L1 fragment certificate: pointwise equivalence on [2,54] for eps=1/1.
    # exact integers only, fail-closed: any mismatch RAISES.
    if not isinstance(witness, dict):
        raise ValueError('witness must be a dict')
    en = witness['epsilon_num']
    ed = witness['epsilon_den']
    lo = witness['scope_lo']
    hi = witness['scope_hi']
    if en <= 0 or ed <= 0:
        raise ValueError('epsilon must be positive')
    if not (isinstance(lo, int) and isinstance(hi, int)) or hi < lo or lo < 2:
        raise ValueError('bad scope')

    def omega(m):
        cnt = 0
        d = 2
        while d * d <= m:
            if m % d == 0:
                cnt += 1
                while m % d == 0:
                    m //= d
            d += 1
        if m > 1:
            cnt += 1
        return cnt

    for n in range(lo, hi + 1):
        # side A: n in B_epsilon: for all m < n: m + (en/ed)*omega(m) <= n
        in_B = True
        for m in range(1, n):
            if m * ed + en * omega(m) > n * ed:
                in_B = False
                break
        # side B: omega(n-k) <= k/epsilon: omega(n-k)*ed <= k*en for k=1..n-1
        omega_cond = True
        for k in range(1, n):
            if omega(n - k) * ed > k * en:
                omega_cond = False
                break
        if in_B != omega_cond:
            raise ValueError('L1 equivalence violated at n=%d' % n)
    return True
